{"code": "fen = "rnbqkbnr/pppp1ppp/8/4p3/4P3/8/PPPP1PPP/RNBQKBNR w KQkq - 0 2"
pos = simulate_move(fen)
moves = sorted(pos["legal_moves"])

def score(fen):
    p = simulate_move(fen)
    if p["game_over"]:
        w = p.get("winner")
        if w == "white":
            return 100000
        elif w == "black":
            return -100000
        else:
            return 0
    b = p["board"]
    mat = {"P":100,"N":320,"B":330,"R":500,"Q":900,"K":0,
           "p":100,"n":320,"b":330,"r":500,"q":900,"k":0}
    total = 0
    center = {"d4","e4","d5","e5"}
    for row in range(8):
        for col in range(8):
            piece = b[row][col]
            if piece == ".":
                continue
            if piece.isupper():
                total += mat[piece]
                sq = chr(ord('a')+col)+str(8-row)
                if sq in center:
                    total += 12
            else:
                total -= mat[piece.lower()]
                sq = chr(ord('a')+col)+str(8-row)
                if sq in center:
                    total -= 12
    # check term
    if p["in_check"]:
        if p["turn"] == "black":
            total += 25
        else:
            total -= 25
    return total

best = None
bestscore = None
for m in moves:
    after = simulate_move(fen, m)
    if after["game_over"]:
        s = score(after["fen"])
    else:
        replies = after["legal_moves"]
        reply_scores = []
        for r in replies:
            p2 = simulate_move(after["fen"], r)
            reply_scores.append(score(p2["fen"]))
        s = min(reply_scores)
    if bestscore is None or s > bestscore:
        bestscore = s
        best = m
    print(m, s)

print("BEST", best, bestscore)
play_move(best)
"}

